insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://cms.buffalotracedistillery.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);
