where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
-- hand (now produced by RARITY in the source module; applied after the inserts landed without it)
update cellar.products p set rarity = v.r::cellar.rarity from (values ('Buffalo Trace Kosher Straight Rye','allocated'),('Colonel E.H. Taylor Distiller''s Council','allocated'),('Colonel E.H. Taylor 18 Year Marriage','lottery'),('Colonel E.H. Taylor Barrel Proof Rye','allocated'),('Colonel E.H. Taylor Bottled in Bond','lottery'),('Colonel E.H. Taylor Cured Oak','allocated'),('Colonel E.H. Taylor Old Fashioned Sour Mash','allocated'),('Colonel E.H. Taylor Warehouse C','lottery'),('Colonel E.H. Taylor Warehouse C Tornado Surviving','lottery'),('Double Eagle Very Rare','unicorn'),('Eagle Rare 25 Year','unicorn'),('Eagle Rare 30 Year','unicorn'),('Old Charter Oak Canadian Oak','limited'),('Old Charter Oak Chinkapin Oak','limited'),('Old Charter Oak Finest Oak','limited'),('Old Charter Oak Mongolian Oak','limited'),('Sazerac Rye 100 Proof','shelf'),('Van Winkle Special Reserve 12 Year','lottery'),('Weller Special Reserve Colorado','allocated')) v(n,r) where p.type='bourbon' and p.merged_into is null and p.rarity is null and p.source='maker' and p.name = v.n;
